// n8n Code node: "Build Safe Summary" (Run Once for All Items) in the error workflow.
// Input: the Error Trigger item ({ execution: {...}, workflow: {...} } or { trigger: {...}, workflow }).
// Output: a notification payload with no tokens, secrets, request bodies or customer emails.
const data = $input.first().json;
const execution = data.execution || {};
const failure = execution.error || (data.trigger && data.trigger.error) || {};
const scrub = (value, max) => String(value == null ? '' : value)
  .replace(/Bearer\s+[A-Za-z0-9._~+\/=-]+/gi, 'Bearer [redacted]')
  .replace(/\bpat-[a-z0-9]{2,4}-[A-Za-z0-9-]+/gi, '[redacted-token]')
  .replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, '[redacted-email]')
  .replace(/\b[a-f0-9]{32,}\b/gi, '[redacted-hex]')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, max);
const httpCode = failure.httpCode || (failure.cause && failure.cause.status) || null;
return [{
  json: {
    source: 'optima-n8n',
    severity: 'error',
    workflowName: scrub((data.workflow && data.workflow.name) || 'unknown workflow', 120),
    workflowId: (data.workflow && data.workflow.id) || null,
    executionId: execution.id || null,
    executionUrl: execution.url || null,
    mode: execution.mode || (data.trigger ? 'trigger' : null),
    failedNode: scrub(execution.lastNodeExecuted || (failure.node && failure.node.name) || 'unknown', 120),
    httpCode: httpCode ? String(httpCode).slice(0, 3) : null,
    errorSummary: scrub(failure.message || 'Workflow failed without an error message', 300),
    timestamp: new Date().toISOString(),
  },
}];
